MUSIC_PROMPT_SYSTEM = """너는 유튜브 명상·집중·수면 음악 채널의 아트 디렉터다. 음악 종류와 제목, 사용자가 적은 분위기에 맞는 배경 이미지 프롬프트를 만든다.
- images: 3개. 서로 다른 장면(예: 자연 풍경 / 실내 공간 / 추상 빛). 각 prompt 는 영어 50~80단어: 장소·시간·빛·색감·질감·구도, 아주 고요하고 움직임이 적은 장면, 사람 없음(or 뒷모습 실루엣), 글자·워터마크 금지.
  화면 비율은 사용자가 알려준 비율. 긴 시간 봐도 피로하지 않게 대비가 부드럽고 어두운 톤 위주.
- video_prompt: 같은 장면을 5~10초짜리 '끊김 없이 반복되는(seamless loop)' 짧은 영상으로 만들 때 쓸 영어 프롬프트 1개(60~90단어). 카메라 고정 또는 아주 느린 줌, 반복 가능한 작은 움직임만(흔들리는 촛불, 떨어지는 비, 흐르는 구름, 반짝이는 별, 물결). 갑작스러운 변화 금지, 글자 금지.
- ko: 각 프롬프트의 한국어 한 줄 설명
반드시 JSON만 출력: {"images": [{"ko": "...", "prompt": "..."}], "video_prompt": "...", "video_ko": "..."}"""
MUSIC_TAIL = 12.0   # 덩어리 사이 겹치는 길이(초)


def piano_note(freq, dur=3.0, vel=0.8, soft=1.0):
    """부드러운 피아노 한 음 (배음 + 높은 배음이 먼저 사라짐)"""
    t = np.arange(int(dur * SR)) / SR
    tau = min(4.0, 1.6 * (262 / freq) ** 0.35)
    s = np.zeros_like(t)
    for k in range(1, 8):
        fk = freq * k * np.sqrt(1 + 0.0004 * k * k)
        if fk > 9000:
            break
        s += np.exp(-(k - 1) * 0.7 * soft) / k * np.sin(2 * np.pi * fk * t) * np.exp(-t * k ** 0.7 / tau)
    s *= np.minimum(1, t / 0.004) * np.clip((dur - t) / 0.3, 0, 1)
    return (s / 1.6 * vel).astype(np.float32)


def epiano_note(freq, dur=2.5, vel=0.8):
    """일렉트릭 피아노(로파이) - FM 방식"""
    t = np.arange(int(dur * SR)) / SR
    idx = 1.4 * np.exp(-t / 0.3) + 0.25
    s = np.sin(2 * np.pi * freq * t + idx * np.sin(2 * np.pi * freq * t)) * np.exp(-t / 1.3)
    s += 0.12 * np.sin(2 * np.pi * 2 * freq * t) * np.exp(-t / 0.35)
    s *= np.minimum(1, t / 0.003) * np.clip((dur - t) / 0.25, 0, 1) * (1 + 0.06 * np.sin(2 * np.pi * 4.5 * t))
    return (s * 0.55 * vel).astype(np.float32)


def bowl_note(freq, dur=11.0, vel=0.8, rng=None):
    """싱잉볼: 비정수 배음 + 맥놀이(두 음이 살짝 어긋나 우웅우웅)"""
    t = np.arange(int(dur * SR)) / SR
    s = np.zeros_like(t)
    for ratio, amp, dec in ((1, 1.0, 8.0), (2.71, 0.45, 5.0), (5.15, 0.22, 3.0), (8.5, 0.1, 1.6)):
        f = freq * ratio
        d = 0.35 + 0.2 * ratio
        s += amp * (np.sin(2 * np.pi * f * t) + np.sin(2 * np.pi * (f + d) * t)) * 0.5 * np.exp(-t / dec)
    s *= np.minimum(1, t / 0.006) * np.clip((dur - t) / 1.5, 0, 1)
    return (s * 0.5 * vel).astype(np.float32)


def bird_call(rng):
    """새소리 한 번 (짹짹 / 휘파람 / 떨림)"""
    kind = rng.integers(3)
    out = []
    if kind == 0:
        for _ in range(rng.integers(3, 7)):
            d = rng.uniform(0.05, 0.11)
            t = np.arange(int(d * SR)) / SR
            f0, f1 = rng.uniform(3800, 5200), rng.uniform(2600, 3600)
            ph = 2 * np.pi * np.cumsum(f0 + (f1 - f0) * t / d) / SR
            out.append(np.sin(ph) * np.sin(np.pi * t / d) ** 2)
            out.append(np.zeros(int(rng.uniform(0.05, 0.1) * SR)))
    elif kind == 1:
        for f0, f1 in ((rng.uniform(2000, 2500), rng.uniform(2700, 3200)), (rng.uniform(2600, 3000), rng.uniform(2000, 2400))):
            d = rng.uniform(0.18, 0.32)
            t = np.arange(int(d * SR)) / SR
            ph = 2 * np.pi * np.cumsum(f0 + (f1 - f0) * (t / d) ** 2) / SR
            out.append(np.sin(ph) * np.sin(np.pi * t / d))
            out.append(np.zeros(int(0.06 * SR)))
    else:
        d = rng.uniform(0.4, 0.8)
        t = np.arange(int(d * SR)) / SR
        f = rng.uniform(3800, 4800)
        out.append(np.sin(2 * np.pi * f * t) * (0.5 + 0.5 * np.sin(2 * np.pi * rng.uniform(14, 22) * t)) * np.sin(np.pi * t / d))
    return np.concatenate(out).astype(np.float32)


def _music_setup(name, seed):
    """곡 전체에서 바뀌지 않는 값(조성·빠르기 등)"""
    P = dict(MUSIC_PRESETS[name])
    rng = np.random.default_rng(seed)
    P["key"] = int(rng.integers(-3, 4))
    if P["gen"] == "lofi":
        P["bpm"] = float(rng.uniform(70, 84))
        P["bar"] = 4 * 60 / P["bpm"]
    elif P["gen"] in ("piano", "rain_piano"):
        P["bpm"] = 64.0 if P["gen"] == "piano" else 56.0
        P["bar"] = 4 * 60 / P["bpm"]
    elif P["gen"] == "jazz":
        P["bpm"] = float(rng.uniform(92, 118))
        P["bar"] = 4 * 60 / P["bpm"]
    elif P["gen"] == "bossa":
        P["bpm"] = float(rng.uniform(124, 138))
        P["bar"] = 4 * 60 / P["bpm"]
    elif P["gen"] == "lullaby":
        notes = parse_melody(P["melody"])
        beat = 60 / P["bpm"]
        P["notes"] = notes
        P["loop"] = (sum(b for _, b in notes) + 4) * beat
        P["bar"] = P["loop"]
    else:
        P["bar"] = 1.0
    return P


LOFI_PROG = [[50, 53, 57, 60, 64], [43, 53, 57, 59, 64], [48, 52, 55, 59, 62], [45, 55, 59, 60, 64]]   # ii9 V13 Imaj9 vi9
PIANO_PROG = {"warm": [[48, 55, 64, 67, 71], [53, 57, 64, 69, 72], [45, 52, 60, 64, 67], [43, 50, 59, 62, 67]],
              "sad": [[45, 52, 60, 64, 67], [41, 48, 57, 60, 65], [48, 55, 64, 67, 72], [43, 50, 59, 62, 67]]}


JAZZ_FORM = [("maj7", 0), ("7", 9), ("m7", 2), ("7", 7), ("m7", 4), ("7", 9), ("m7", 2), ("7", 7)]   # I VI ii V iii VI ii V
BOSSA_FORM = [("maj7", 0), ("maj7", 0), ("7", 2), ("7", 2), ("m7", 2), ("7", 7), ("maj7", 0), ("7", 7)]   # I II7 ii V
CHORD_TONES = {"maj7": [0, 4, 7, 11, 14], "7": [0, 4, 7, 10, 14], "m7": [0, 3, 7, 10, 14]}


def upright_bass(freq, dur=0.6, vel=0.8):
    t = np.arange(int(dur * SR)) / SR
    s = np.sin(2 * np.pi * freq * t) + 0.35 * np.sin(4 * np.pi * freq * t) * np.exp(-t / 0.12) + 0.1 * np.sin(6 * np.pi * freq * t) * np.exp(-t / 0.05)
    return (s * np.exp(-t / 0.45) * np.minimum(1, t / 0.006) * np.clip((dur - t) / 0.05, 0, 1) * vel * 0.6).astype(np.float32)


def ride_hit(rng, vel=0.5):
    t = np.arange(int(0.9 * SR)) / SR
    nz = band(rng.standard_normal(len(t)).astype(np.float32), lo=4000, hi=12000)
    ping = sum(np.sin(2 * np.pi * f * t) for f in (3150, 4720, 6380)) / 3
    return ((_norm(nz) * 0.5 + ping * 0.25) * np.exp(-t / 0.35) * np.minimum(1, t / 0.001) * vel).astype(np.float32)


def brush(rng, vel=0.3, dur=0.28):
    t = np.arange(int(dur * SR)) / SR
    nz = band(rng.standard_normal(len(t)).astype(np.float32), lo=1500, hi=7000)
    return (_norm(nz) * np.sin(np.pi * t / dur) ** 1.5 * vel).astype(np.float32)


def cafe_bed(L, rng):
    """카페 소리: 웅성거림 + 가끔 커피잔·숟가락 소리"""
    mur = []
    for _ in range(2):
        x = band(colored_noise(L, rng, 1.0), lo=250, hi=2600)
        mod = smooth_lfo(L, 0.18, rng, 0.5, 1.0) * smooth_lfo(L, 1.7, rng, 0.7, 1.0)
        mur.append(_norm(x) * mod * 0.55 + _norm(band(colored_noise(L, rng, 2.0), hi=200)) * 0.2)
    bed = np.stack(mur, 1)
    pos = rng.uniform(1, 5)
    while pos < L / SR - 2:
        f0 = rng.uniform(2400, 4200)
        clink = (bell(f0, 0.8) * 0.12 + bell(f0 * 1.47, 0.8) * 0.06).astype(np.float32)
        place(bed, clink, pos, rng.uniform(0.15, 0.85))
        pos += rng.exponential(5.0) + 1.0
    return bed


def _drum(kind, rng):
    if kind == "kick":
        t = np.arange(int(0.35 * SR)) / SR
        f = 45 + 75 * np.exp(-t / 0.04)
        return (np.sin(2 * np.pi * np.cumsum(f) / SR) * np.exp(-t / 0.18)).astype(np.float32)
    if kind == "snare":
        t = np.arange(int(0.25 * SR)) / SR
        nz = band(rng.standard_normal(len(t)).astype(np.float32), lo=1200, hi=6000)
        return (_norm(nz) * np.exp(-t / 0.07) * 0.6 + np.sin(2 * np.pi * 185 * t) * np.exp(-t / 0.05) * 0.4).astype(np.float32)
    t = np.arange(int(0.06 * SR)) / SR
    return (band(rng.standard_normal(len(t)).astype(np.float32), lo=6000) * np.exp(-t / 0.015) * 3).astype(np.float32)


def music_chunk(P, n, tail, rng, ci):
    """음악 한 덩어리 → (사건 소리, 바탕 소리) 둘 다 (n+tail, 2). 사건은 [0, n) 안에서 시작해 tail 안에서 끝남"""
    g, L = P["gen"], n + tail
    T0 = ci * n / SR
    ev = np.zeros((L, 2), np.float32)
    bed = None
    tsec = n / SR
    if g == "bowls":
        roots = [midi_hz(m + P["key"]) for m in (57, 60, 62, 64, 67, 69)]
        pos = rng.uniform(0.5, 3)
        while pos < tsec:
            place(ev, bowl_note(rng.choice(roots) * rng.choice([0.5, 1, 1]), 11, rng.uniform(0.5, 0.9)), pos, rng.uniform(0.25, 0.75))
            pos += rng.uniform(7, 14)
        ev = reverb(ev, rng, 4.0, 0.4)
        bed = gen_pad(L, rng, "space", 14, 700) * 0.35 + np.stack([_norm(band(colored_noise(L, rng, 1.0), lo=200, hi=1800)) for _ in range(2)], 1) * 0.06
    elif g == "sleep":
        bed = gen_pad(L, rng, "warm", 14, 900) * 0.8 + np.stack([_norm(band(colored_noise(L, rng, 2.0), hi=300)) for _ in range(2)], 1) * 0.12
        pos = rng.uniform(2, 6)
        while pos < tsec:
            m = rng.choice([60, 64, 67, 69, 72]) + P["key"]
            place(ev, piano_note(midi_hz(m), 6, rng.uniform(0.15, 0.3), 1.6), pos, rng.uniform(0.3, 0.7))
            pos += rng.uniform(6, 13)
        ev = reverb(ev, rng, 4.0, 0.5)
    elif g == "lofi":
        beat = 60 / P["bpm"]
        bars = int(round(tsec / P["bar"]))
        sw = 0.58
        kick, snare = _drum("kick", rng), _drum("snare", rng)
        mel = np.zeros((L, 2), np.float32)
        drums = np.zeros((L, 2), np.float32)
        for b in range(bars):
            bt = b * P["bar"]
            gb = ci * bars + b
            ch = [m + P["key"] for m in LOFI_PROG[gb % 4]]
            for j, m in enumerate(ch):
                place(mel, epiano_note(midi_hz(m), P["bar"] * 0.95, rng.uniform(0.45, 0.6)), bt + j * 0.012, 0.35 + 0.075 * j)
            if rng.random() < 0.5:
                for j, m in enumerate(ch[1:]):
                    place(mel, epiano_note(midi_hz(m), beat * 1.5, 0.28), bt + 2.5 * beat + j * 0.01, 0.4 + 0.07 * j)
            root = midi_hz(ch[0] - 12)
            for bb in (0, 2.5):
                tt = np.arange(int(beat * 1.4 * SR)) / SR
                bass = (np.sin(2 * np.pi * root * tt) * np.exp(-tt / 0.6) * np.minimum(1, tt / 0.01)).astype(np.float32)
                place(mel, bass * 0.5, bt + bb * beat, 0.5)
            if rng.random() < 0.35:   # 짧은 피아노 멜로디
                scale = [ch[0] + 24 + x for x in (0, 2, 4, 7, 9, 12)]
                tt = bt + rng.choice([1, 2]) * beat
                for _ in range(rng.integers(3, 6)):
                    place(mel, piano_note(midi_hz(rng.choice(scale)), 1.8, rng.uniform(0.18, 0.3)), tt, rng.uniform(0.4, 0.7))
                    tt += rng.choice([0.5, 0.5, 1]) * beat
            for k in (0, 2.5):
                place(drums, kick * 0.9, bt + k * beat, 0.5)
            if rng.random() < 0.3:
                place(drums, kick * 0.5, bt + 1.75 * beat, 0.5)
            for k in (1, 3):
                place(drums, snare * 0.45, bt + k * beat + rng.uniform(0, 0.012), 0.5)
            for e in range(8):
                if rng.random() < 0.9:
                    off = (e // 2) * beat + (sw * beat if e % 2 else 0)
                    place(drums, _drum("hat", rng) * rng.uniform(0.12, 0.22), bt + off, 0.62)
        mel = reverb(mel, rng, 1.8, 0.22)
        ev = np.stack([band(mel[:, c], hi=6500) for c in range(2)], 1) * 0.9 + np.stack([band(drums[:, c], hi=8000) for c in range(2)], 1) * 0.7
        crk = np.zeros(L, np.float32)
        k = int(L / SR * 6)
        crk[rng.integers(0, L, k)] = rng.uniform(0.2, 1, k)
        vinyl = band(crk + colored_noise(L, rng, 1.0) * 0.02, lo=800, hi=5000)
        bed = np.stack([vinyl, vinyl], 1) * 0.08
    elif g in ("piano", "rain_piano"):
        beat = 60 / P["bpm"]
        prog = PIANO_PROG["warm" if g == "piano" else "sad"]
        bars = int(round(tsec / P["bar"]))
        for b in range(bars):
            bt = b * P["bar"]
            gb = ci * bars + b
            ch = [m + P["key"] for m in prog[(gb // 2) % 4]]
            place(ev, piano_note(midi_hz(ch[0] - 12), P["bar"] * 1.6, 0.45), bt, 0.45)
            dens = 0.75 if g == "piano" else 0.5
            for e in range(8):
                if rng.random() < dens:
                    m = ch[1:][e % 4] + (12 if rng.random() < 0.2 else 0)
                    place(ev, piano_note(midi_hz(m), 3.0, rng.uniform(0.25, 0.42)), bt + e * beat / 2 + rng.uniform(0, 0.015), rng.uniform(0.3, 0.7))
        ev = reverb(ev, rng, 3.2, 0.38)
        if g == "rain_piano":
            bed = gen_rain(L, rng) * 0.42
    elif g == "rain":
        bed = gen_rain(L, rng)
        if rng.random() < 0.35:   # 먼 천둥
            d = 6.0
            tt = np.arange(int(d * SR)) / SR
            th = band(colored_noise(len(tt), rng, 2.0), hi=180) * np.minimum(1, tt / 0.6) * np.exp(-tt / 2.2)
            place(ev, (_norm(th) * 0.5).astype(np.float32), rng.uniform(5, max(6, tsec - 8)), rng.uniform(0.3, 0.7))
    elif g == "roof":
        # 바탕: 멀리 쏟아지는 비 (부드럽게)
        bed = gen_rain(L, rng) * 0.45
        # 지붕에 맞는 빗방울: 톡·탁 (울림 있는 짧은 소리)
        drops = np.zeros((L, 2), np.float32)
        rate = 9.0 * (0.75 + 0.5 * smooth_lfo(n, 20, rng))     # 초당 빗방울 수가 천천히 바뀜
        cnt = int(n / SR * 9)
        pos = np.sort(rng.uniform(0, n / SR, cnt))
        keep = rng.random(cnt) < rate[np.minimum((pos * SR).astype(int), n - 1)] / 13.5
        kinds = []
        for f0 in (650, 900, 1250, 1800, 2400):    # 기와·양철에 따라 다른 높이
            tt = np.arange(int(0.05 * SR)) / SR
            kinds.append((np.sin(2 * np.pi * f0 * tt) * np.exp(-tt / 0.008) + rng.standard_normal(len(tt)) * np.exp(-tt / 0.002) * 0.6).astype(np.float32))
        for ps in pos[keep]:
            k = kinds[int(rng.integers(len(kinds)))] * rng.uniform(0.15, 0.6)
            place(drops, k, ps, rng.uniform(0.1, 0.9))
        drops = np.stack([band(drops[:, c], lo=400, hi=6000) for c in range(2)], 1)
        # 처마 끝 낙숫물: 일정한 간격으로 똑… 똑
        drip = np.zeros((L, 2), np.float32)
        for side in (0.25, 0.75):
            t_ = rng.uniform(0, 1.0)
            per = rng.uniform(0.6, 1.4)
            while t_ < n / SR:
                tt = np.arange(int(0.12 * SR)) / SR
                f = rng.uniform(1100, 1500) * (1 + 0.6 * np.exp(-tt / 0.01))
                d_ = (np.sin(2 * np.pi * np.cumsum(f) / SR) * np.exp(-tt / 0.03) * rng.uniform(0.2, 0.35)).astype(np.float32)
                place(drip, d_, t_, side)
                t_ += per * rng.uniform(0.85, 1.15)
        ev = reverb(drops * 0.9 + drip, rng, 1.2, 0.25)
    elif g == "waves":
        bed = gen_waves(L, rng)
    elif g == "forest":
        lfo = smooth_lfo(L, 0.4, rng, 0.6, 1.0)
        bed = np.stack([_norm(band(colored_noise(L, rng, 1.0), lo=300, hi=3000)) * lfo * 0.35
                        + _norm(band(colored_noise(L, rng, 2.0), hi=250)) * 0.15 for _ in range(2)], 1)
        pos = rng.uniform(0.5, 2)
        while pos < tsec:
            c = bird_call(rng)
            dist = rng.uniform(0.25, 1.0)
            if dist < 0.5:
                c = band(c, hi=3500)
            place(ev, c * 0.35 * dist, pos, rng.uniform(0.1, 0.9))
            pos += rng.uniform(1.2, 5.5)
        ev = reverb(ev, rng, 1.8, 0.3)
    elif g == "fire":
        bed = np.stack([_norm(band(colored_noise(L, rng, 2.0), hi=300)) * (0.7 + 0.3 * smooth_lfo(L, 1.5, rng)) * 0.6
                        + _norm(band(colored_noise(L, rng, 1.0), lo=900, hi=4000)) * 0.08 for _ in range(2)], 1)
        imp = np.zeros((L, 2), np.float32)
        pos = 0.0
        while pos < tsec:
            burst = rng.integers(1, 6)
            for _ in range(burst):
                i = int((pos + rng.uniform(0, 0.25)) * SR)
                if i < n:
                    p_ = rng.uniform(0.2, 0.8)
                    a = rng.uniform(0.3, 1.0) * (1.8 if rng.random() < 0.06 else 1)
                    imp[i, 0] += a * (1 - p_)
                    imp[i, 1] += a * p_
            pos += rng.exponential(0.5)
        kl = int(0.012 * SR)
        kern = (rng.standard_normal(kl) * np.exp(-np.arange(kl) / (0.002 * SR))).astype(np.float32)
        ev = np.stack([band(ola_conv(imp[:, c], kern), lo=1200, hi=7000) for c in range(2)], 1) * 0.6
    elif g == "brown":
        bed = np.stack([_norm(band(colored_noise(L, rng, 2.0), hi=500)) * (0.92 + 0.08 * smooth_lfo(L, 6, rng)) for _ in range(2)], 1)
    elif g == "binaural":
        t = (np.arange(L) / SR + T0)       # 전체 시간 기준 → 덩어리가 바뀌어도 위상이 이어짐
        fc, fb = P["carrier"], P["beat"]
        tone = np.stack([np.sin(2 * np.pi * fc * t), np.sin(2 * np.pi * (fc + fb) * t)], 1).astype(np.float32) * 0.3
        bed = tone + gen_pad(L, rng, "space", 14, 800) * 0.35 + np.stack([_norm(band(colored_noise(L, rng, 1.0), hi=1200)) for _ in range(2)], 1) * 0.05
    elif g == "jazz":
        beat = 60 / P["bpm"]
        sw = 0.66          # 스윙 (셋잇단 느낌)
        bars = int(round(tsec / P["bar"]))
        root0 = 48 + P["key"]
        bass, piano, drums = (np.zeros((L, 2), np.float32) for _ in range(3))
        for b in range(bars):
            bt = b * P["bar"]
            gb = ci * bars + b
            q, r_ = JAZZ_FORM[gb % 8]
            nq, nr = JAZZ_FORM[(gb + 1) % 8]
            root = root0 - 12 + r_
            tones = CHORD_TONES[q]
            nxt = root0 - 12 + nr
            walk = [root, root + rng.choice(tones[1:3]), root + rng.choice([7, 12, tones[1]]), nxt + rng.choice([-1, 1, 2])]
            for k, m in enumerate(walk):
                place(bass, upright_bass(midi_hz(m), beat * 0.95, 0.85 if k == 0 else 0.7), bt + k * beat + rng.uniform(0, 0.01), 0.45)
            for k in range(4):   # 라이드 심벌 '칭 칭-가 칭 칭-가'
                place(drums, ride_hit(rng, 0.32 if k % 2 == 0 else 0.4), bt + k * beat, 0.62)
                if k % 2 == 1:
                    place(drums, ride_hit(rng, 0.22), bt + k * beat + sw * beat, 0.62)
                    place(drums, brush(rng, 0.22), bt + k * beat, 0.45)
            voic = [root0 + r_ + tones[1], root0 + r_ + tones[3], root0 + r_ + tones[4]]   # 루트 없는 보이싱(3·7·9)
            for hit in ([1 + sw] if rng.random() < 0.6 else [0]) + ([3] if rng.random() < 0.5 else []):
                for j, m in enumerate(voic):
                    place(piano, piano_note(midi_hz(m), beat * 1.6, rng.uniform(0.18, 0.26)), bt + hit * beat + j * 0.008, 0.4 + 0.08 * j)
            if (gb // 2) % 2 == 1 and rng.random() < 0.85:   # 2마디씩 즉흥 멜로디
                scale = [root0 + 12 + r_ + x for x in tones] + [root0 + 24 + r_ + tones[0]]
                tt, idx = bt, int(rng.integers(len(scale)))
                while tt < bt + P["bar"] - 0.1:
                    if rng.random() < 0.8:
                        place(piano, piano_note(midi_hz(scale[idx]), 1.0, rng.uniform(0.22, 0.32), 1.3), tt, 0.55)
                    idx = int(np.clip(idx + rng.choice([-2, -1, 1, 1, 2]), 0, len(scale) - 1))
                    step = sw * beat if ((tt - bt) / beat) % 1 < 0.1 else (1 - sw) * beat
                    tt += step if rng.random() < 0.75 else beat
        ev = reverb(piano, rng, 1.6, 0.25) + reverb(bass, rng, 1.0, 0.12) * 1.1 + reverb(drums, rng, 1.4, 0.2) * 0.8
        ev = np.stack([band(ev[:, c], hi=9000) for c in range(2)], 1)
        if P.get("cafe"):
            bed = cafe_bed(L, rng) * 0.55
    elif g == "bossa":
        beat = 60 / P["bpm"]
        bars = int(round(tsec / P["bar"]))
        root0 = 48 + P["key"]
        gtr, perc, mel = (np.zeros((L, 2), np.float32) for _ in range(3))
        shaker = brush(rng, 0.12, 0.08)
        for b in range(bars):
            bt = b * P["bar"]
            gb = ci * bars + b
            q, r_ = BOSSA_FORM[gb % 8]
            tones = CHORD_TONES[q]
            root = root0 - 12 + r_
            for k, m in ((0, root), (1.5, root + 7), (2, root), (3.5, root + 7)):   # 엄지 베이스
                place(gtr, pluck(midi_hz(m), 1.0) * 0.6, bt + k * beat, 0.45)
            ch = [root0 + r_ + x for x in (tones[1], tones[2], tones[3], tones[4])]
            for e in ((0, 1.5, 2.5) if gb % 2 == 0 else (0.5, 1.5, 3)):   # 보사노바 손가락 리듬
                for j, m in enumerate(ch):
                    place(gtr, pluck(midi_hz(m), 0.9) * 0.28, bt + e * beat + j * 0.006, 0.55)
            for e in range(8):
                place(perc, shaker * (1.2 if e % 2 else 0.8), bt + e * beat / 2, 0.68)
            for k in ((0, 1.5, 3) if gb % 2 == 0 else (1, 2.5)):   # 림 클릭(클라베)
                tt_ = np.arange(int(0.05 * SR)) / SR
                place(perc, (np.sin(2 * np.pi * 1700 * tt_) * np.exp(-tt_ / 0.01) * 0.25).astype(np.float32), bt + k * beat, 0.4)
            if (gb // 4) % 2 == 1 and rng.random() < 0.8:
                scale = [root0 + 12 + r_ + x for x in (0, 2, 4, 7, 9, 12)]
                tt = bt + rng.choice([0, 0.5]) * beat
                while tt < bt + P["bar"] - 0.2:
                    place(mel, piano_note(midi_hz(rng.choice(scale)), 1.4, rng.uniform(0.2, 0.3), 1.2), tt, 0.5)
                    tt += rng.choice([0.5, 1, 1, 1.5]) * beat
        ev = reverb(gtr, rng, 1.4, 0.18) + reverb(mel, rng, 2.0, 0.3) + perc * 0.8
        ev = np.stack([band(ev[:, c], hi=10000) for c in range(2)], 1)
    elif g == "lullaby":
        beat = 60 / P["bpm"]
        loop = P["loop"]
        PROGS["_lull"] = _melody_chords(P["notes"])
        bed = gen_pad(L, rng, "_lull", 8 * beat, 1300) * 0.3
        k0 = int(T0 // loop)
        cache = {}
        for k in range(k0, k0 + int(tsec // loop) + 2):
            t = k * loop + beat
            for midi, b in P["notes"]:
                if midi is not None and T0 <= t < T0 + tsec:
                    m = midi + 12 + P["key"]
                    if m not in cache:
                        cache[m] = pluck(midi_hz(m), 2.2)
                    place(ev, cache[m] * rng.uniform(0.6, 0.85), t - T0, 0.5 + 0.2 * np.sin(t))
                t += b * beat
        ev = reverb(ev, rng, 2.8, 0.35)
    elif g == "space":
        bed = gen_space(L, rng)
    return ev, bed


def render_music_track(name, minutes, seed, wav_path, progress=None, cancel=None):
    """음악 트랙을 덩어리(약 90초)씩 만들어 이어 붙여 WAV로 저장 (긴 곡도 메모리 적게). 반환: 길이(초)"""
    import wave
    P = _music_setup(name, seed)
    bar = P.get("bar", 1.0)
    N = int(round(max(1, round(90 / bar)) * bar * SR))
    tail = int(MUSIC_TAIL * SR)
    total = int(max(0.2, float(minutes)) * 60 * SR)
    nch = int(np.ceil(total / N))
    carry = np.zeros((tail, 2), np.float32)
    fade_in, fade_out = int(3 * SR), int(min(10, total / SR / 4) * SR)
    gain = None
    os.makedirs(os.path.dirname(os.path.abspath(wav_path)), exist_ok=True)
    written = 0
    with wave.open(wav_path, "wb") as w:
        w.setnchannels(2)
        w.setsampwidth(2)
        w.setframerate(SR)
        for ci in range(nch):
            if cancel is not None and cancel.is_set():
                raise RuntimeError("취소됨")
            rng = np.random.default_rng(seed * 1009 + ci)
            ev, bed = music_chunk(P, N, tail, rng, ci)
            buf = ev.astype(np.float32)
            if bed is not None:
                win = np.ones(N + tail, np.float32)
                if ci > 0:
                    win[:tail] = np.linspace(0, 1, tail)
                win[N:] = np.linspace(1, 0, tail)
                buf = buf + bed.astype(np.float32) * win[:, None]
            buf[:tail] += carry
            carry = buf[N:].copy()
            out = buf[:N]
            if gain is None:   # 첫 덩어리로 소리 크기를 정하고 끝까지 같은 크기 유지
                rms = float(np.sqrt((out ** 2).mean())) + 1e-9
                target = 0.09 if P["gen"] in ("bowls", "sleep", "binaural", "lullaby", "space") else 0.12
                gain = target / rms
            out = out * gain
            a = ci * N
            idx = np.arange(a, a + N)
            env = np.minimum(1, idx / fade_in) * np.clip((total - idx) / fade_out, 0, 1)
            out = out * env[:, None]
            out = np.where(np.abs(out) > 0.8, np.sign(out) * (0.8 + 0.15 * np.tanh((np.abs(out) - 0.8) / 0.15)), out)
            k = min(N, total - written)
            if k <= 0:
                break
            w.writeframes((np.clip(out[:k], -1, 1) * 32767).astype("<i2").tobytes())
            written += k
            if progress:
                progress(ci + 1, nch)
    return written / SR


def trim_borders(im, max_frac=0.12):
    """그림 가장자리의 검은 띠·점선(AI 그림에 가끔 생김)을 잘라냄"""
    a = np.asarray(im.convert("L")).astype(np.float32)
    h, w = a.shape

    def is_border(v):
        return v.mean() < 28 and np.percentile(v, 80) < 60
    l = 0
    while l < int(w * max_frac) and is_border(a[:, l]):
        l += 1
    r = w
    while w - r < int(w * max_frac) and is_border(a[:, r - 1]):
        r -= 1
    t_ = 0
    while t_ < int(h * max_frac) and is_border(a[t_, :]):
        t_ += 1
    b = h
    while h - b < int(h * max_frac) and is_border(a[b - 1, :]):
        b -= 1
    if (l, t_, r, b) != (0, 0, w, h):
        m = 2   # 띠와 맞닿은 줄까지 조금 더 잘라냄 (잘라낸 쪽만)
        l, t_ = (l + m if l else 0), (t_ + m if t_ else 0)
        r, b = (r - m if r < w else w), (b - m if b < h else h)
        return im.crop((min(l, w // 2), min(t_, h // 2), max(r, w // 2), max(b, h // 2)))
    return im


class MusicLoop:
    """음악 영상의 그림 부분: 배경 그림이 천천히 줌인·줌아웃(끊김 없이 반복) + 입자 효과 + 제목. duration 초짜리 반복 조각"""

    def __init__(self, s, bg_image, overlay, title, sub, colors, show_text=True, L=32.0, motion="천천히 줌"):
        self.s, self.duration, self.L, self.motion = s, L, L, motion
        self.overlay, self.title, self.sub, self.show_text = overlay, title, sub, show_text
        if bg_image is not None:
            im = trim_borders(bg_image.convert("RGB"))
        else:
            c1, c2 = np.array(hex_rgb(colors[0]), np.float32), np.array(hex_rgb(colors[1]), np.float32)
            g = np.linspace(0, 1, H, dtype=np.float32)[:, None, None]
            im = Image.fromarray(np.broadcast_to(c1 + (c2 - c1) * g, (H, W, 3)).astype(np.uint8))
        k = max(W / im.width, H / im.height) * 1.12
        self.big = im.resize((int(im.width * k) + 2, int(im.height * k) + 2), Image.LANCZOS)
        yy, xx = np.mgrid[0:H, 0:W].astype(np.float32)
        r = np.sqrt(((xx - W / 2) / (W / 2)) ** 2 + ((yy - H / 2) / (H / 2)) ** 2) / 1.42
        self.vig = (1 - 0.35 * np.clip(r, 0, 1) ** 2)[..., None].astype(np.float32)
        rng = np.random.default_rng(5)
        self.parts = rng.uniform(0, 1, (160, 6))
        self.glow = {}
        self.text_layer = self._make_text()

    def _sprite(self, r, col):
        key = (r, col)
        if key not in self.glow:
            sz = r * 6
            yy, xx = np.mgrid[0:sz, 0:sz].astype(np.float32) - sz / 2
            a = np.exp(-(xx ** 2 + yy ** 2) / (2 * (r * 0.9) ** 2))
            arr = np.zeros((sz, sz, 4), np.uint8)
            arr[..., :3] = col
            arr[..., 3] = np.clip(a * 255, 0, 255).astype(np.uint8)
            self.glow[key] = Image.fromarray(arr, "RGBA")
        return self.glow[key]

    def _make_text(self):
        layer = Image.new("RGBA", (W, H), (0, 0, 0, 0))
        if not self.show_text or not self.title.strip():
            return layer
        d = ImageDraw.Draw(layer)
        port = H > W
        fp = self.s.get("title_font_path") or self.s.get("font_path")
        size = int(H * (0.034 if port else 0.05))
        f1 = load_font(fp, size)
        f2 = load_font(self.s.get("font_path"), int(size * 0.6))
        clean = re.sub(r"[\U0001F000-\U0001FFFF\u2600-\u27BF\uFE0F]", "", self.title).strip()   # 이모지는 화면 글꼴에 없음
        clean = re.sub(r"\s+", " ", clean)
        lines = wrap(clean, f1, W * (0.86 if port else 0.6))[:2]
        m = int(W * 0.06)
        y = int(H * (0.8 if port else 0.74))
        for ln in lines:
            x = (W - f1.getlength(ln)) / 2 if port else m
            d.text((x + 2, y + 3), ln, font=f1, fill=(0, 0, 0, 140))
            d.text((x, y), ln, font=f1, fill=(255, 255, 255, 235))
            y += int(size * 1.25)
        if self.sub:
            x = (W - f2.getlength(self.sub)) / 2 if port else m
            d.text((x, y + 6), self.sub, font=f2, fill=(255, 255, 255, 170))
        return layer

    def frame(self, t):
        L = self.L
        ph = (t % L) / L
        mo = self.motion
        s_, c_ = np.sin(2 * np.pi * ph), 0.5 - 0.5 * np.cos(2 * np.pi * ph)
        if mo.startswith("없음"):
            z, dx, dy = 1.06, 0.0, 0.0
        elif mo.startswith("숨쉬듯"):
            z, dx, dy = 1.0 + 0.1 * (0.5 - 0.5 * np.cos(4 * np.pi * ph)), 0.0, 0.0
        elif mo.startswith("좌우"):
            z, dx, dy = 1.1, s_ * 0.9, 0.0
        elif mo.startswith("위아래"):
            z, dx, dy = 1.1, 0.0, s_ * 0.9
        elif mo.startswith("천천히 줌인"):
            z, dx, dy = 1.0 + 0.1 * c_, 0.0, 0.0
        else:   # 천천히 줌 (다가갔다 물러남 + 살짝 흐름) → 끝과 처음이 이어짐
            z, dx, dy = 1.0 + 0.07 * c_, s_ * 0.25, np.sin(4 * np.pi * ph) * 0.1
        cw, ch = W * 1.12 / z, H * 1.12 / z
        cx = self.big.width / 2 + dx * (self.big.width - cw) / 2
        cy = self.big.height / 2 + dy * (self.big.height - ch) / 2
        bg = self.big.transform((W, H), Image.EXTENT, (cx - cw / 2, cy - ch / 2, cx + cw / 2, cy + ch / 2), Image.BILINEAR)
        arr = (np.asarray(bg).astype(np.float32) * self.vig * 0.92).astype(np.uint8)
        im = Image.fromarray(arr).convert("RGBA")
        ov = self.overlay
        P = self.parts
        if ov in ("먼지 빛", "반딧불"):
            cnt = 45 if ov == "먼지 빛" else 35
            col = (255, 240, 200) if ov == "먼지 빛" else (255, 220, 120)
            for i in range(cnt):
                x0, y0, a1, a2, p1, p2 = P[i]
                kx, ky = 1 + int(a1 * 2), 1 + int(a2 * 2)
                x = (x0 + 0.04 * np.sin(2 * np.pi * (ph * kx + p1))) * W
                y = ((y0 - ph * (1 if ov == "먼지 빛" else 0)) % 1.0 + 0.03 * np.sin(2 * np.pi * (ph * ky + p2))) * H
                br = 0.5 + 0.5 * np.sin(2 * np.pi * (ph * (2 + int(p1 * 3)) + p2))
                r = 3 + int(a1 * 4) if ov == "먼지 빛" else 4 + int(a2 * 5)
                sp = self._sprite(r, col)
                if br > 0.05:
                    a = sp.getchannel("A").point(lambda v, br=br: int(v * br * (0.7 if ov == "먼지 빛" else 1)))
                    s2 = sp.copy()
                    s2.putalpha(a)
                    im.alpha_composite(s2, (int(x - sp.width / 2), int(y - sp.height / 2)))
        elif ov == "눈":
            for i in range(120):
                x0, y0, a1, a2, p1, p2 = P[i]
                y = ((y0 + ph * (1 + int(a2 * 2))) % 1.0) * (H + 20) - 10
                x = (x0 + 0.02 * np.sin(2 * np.pi * (ph * 3 + p1))) * W
                r = 2 + int(a1 * 4)
                im.alpha_composite(self._sprite(r, (255, 255, 255)), (int(x - r * 3), int(y - r * 3)))
        elif ov == "빗줄기":
            d = ImageDraw.Draw(im)
            for i in range(150):
                x0, y0, a1, a2, p1, p2 = P[i]
                y = ((y0 + ph * (6 + int(a2 * 4))) % 1.0) * (H + 80) - 40
                x = x0 * (W + 60) - 30
                ln = 25 + a1 * 35
                d.line([(x, y), (x - ln * 0.18, y + ln)], fill=(200, 220, 255, int(40 + 50 * a1)), width=2)
        elif ov == "호흡 가이드":   # 4초 들이쉬기 - 4초 멈춤 - 4초 내쉬기 - 4초 멈춤 (반복)
            tc = t % 16
            if tc < 4:
                k_, lab = smoothstep(tc / 4), "들이쉬기"
            elif tc < 8:
                k_, lab = 1.0, "멈춤"
            elif tc < 12:
                k_, lab = 1 - smoothstep((tc - 8) / 4), "내쉬기"
            else:
                k_, lab = 0.0, "멈춤"
            r = int(min(W, H) * (0.08 + 0.1 * k_))
            cx_, cy_ = W // 2, int(H * (0.42 if H > W else 0.42))
            ring = Image.new("RGBA", (W, H), (0, 0, 0, 0))
            d = ImageDraw.Draw(ring)
            d.ellipse([cx_ - r, cy_ - r, cx_ + r, cy_ + r], fill=(255, 255, 255, 38), outline=(255, 255, 255, 160), width=4)
            f = load_font(self.s.get("font_path"), int(min(W, H) * 0.035))
            d.text((cx_ - f.getlength(lab) / 2, cy_ - f.size * 0.6), lab, font=f, fill=(255, 255, 255, 220))
            im.alpha_composite(ring)
        im.alpha_composite(self.text_layer)
        return np.asarray(im.convert("RGB")).copy()

    def frame_preview(self, t):
        return np.asarray(Image.fromarray(self.frame(t)).resize((PREVIEW_W, PREVIEW_H), Image.BILINEAR)).copy()


def video_loop(src, out_mp4, text_layer, fps, quality, sec=32.0):
    """짧은 반복 영상 → 화면 크기에 맞게 잘라 sec 초 반복 조각으로 (제목 글자 PNG를 위에 올림)"""
    png = out_mp4 + ".text.png"
    cmd = [get_ffmpeg(), "-y", "-v", "error", "-stream_loop", "-1", "-i", src]
    vf = f"scale={W}:{H}:force_original_aspect_ratio=increase,crop={W}:{H},fps={fps},format=yuv420p"
    if text_layer is not None:
        text_layer.save(png)
        cmd += ["-i", png, "-filter_complex", f"[0:v]{vf}[bg];[bg][1:v]overlay=0:0:format=auto,format=yuv420p[v]", "-map", "[v]"]
    else:
        cmd += ["-vf", vf]
    cmd += ["-an", "-t", f"{sec:.2f}", "-c:v", "libx264", "-preset", "fast", "-crf", str(max(10, min(30, int(quality)))), "-g", str(fps * 2),
            "-movflags", "+faststart", out_mp4]
    p = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, errors="replace",
                       creationflags=(subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0))
    try:
        os.remove(png)
    except OSError:
        pass
    if p.returncode != 0:
        raise RuntimeError("루프 영상 변환 실패: " + (p.stderr or "")[-400:])


def mux_music_video(loop_mp4, wav, out_mp4, sec):
    """그림 반복 조각 + 음악 → 최종 MP4 (그림은 다시 인코딩하지 않아 빠름). sec 초에서 정확히 끝냄"""
    cmd = [get_ffmpeg(), "-y", "-v", "error", "-stream_loop", "-1", "-i", loop_mp4, "-i", wav,
           "-map", "0:v:0", "-map", "1:a:0", "-c:v", "copy", "-c:a", "aac", "-b:a", "160k", "-t", f"{sec:.3f}", "-movflags", "+faststart", out_mp4]
    p = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, errors="replace",
                       creationflags=(subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0))
    if p.returncode != 0:
        raise RuntimeError("음악 영상 합치기 실패: " + (p.stderr or "")[-400:])


def concat_videos(mp4s, out_mp4):
    """같은 설정으로 만든 MP4 여러 개를 다시 인코딩 없이 이어 붙이기"""
    lst = out_mp4 + ".list.txt"
    with open(lst, "w", encoding="utf-8") as f:
        for p in mp4s:
            f.write("file '" + os.path.abspath(p).replace("'", "'\\''") + "'\n")
    cmd = [get_ffmpeg(), "-y", "-v", "error", "-f", "concat", "-safe", "0", "-i", lst, "-c", "copy", "-movflags", "+faststart", out_mp4]
    p = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, errors="replace",
                       creationflags=(subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0))
    try:
        os.remove(lst)
    except OSError:
        pass
    if p.returncode != 0:
        raise RuntimeError("이어 붙이기 실패(화면 크기·fps가 같은 영상끼리만 됩니다): " + (p.stderr or "")[-400:])


MUSIC_PACKAGE_SYSTEM = """너는 구독자 100만 명상·수면·공부 음악 유튜브 채널 운영자다. 음악 영상 업로드 문구를 만든다.
- titles: 5개. 검색에 잘 걸리는 키워드(예: 파도소리, 수면음악, 백색소음, 공부음악, ASMR)를 앞쪽에, 길이(예: 1시간, 3시간)를 넣고, 이모지 0~2개, 45자 이내.
  서로 다른 각도: 상황형(잠 안 올 때·공부할 때) / 감성형 / 키워드 나열형(| 로 구분) / 질문·권유형 / 장소·장면형.
- description: 6~10줄. 첫 줄은 검색 미리보기에 보이는 핵심 한 줄. 어떤 소리인지 감각적으로 2~3줄, 이럴 때 들으세요(수면·공부·명상·휴식) 목록 3~4개(이모지 머리표),
  구독·좋아요 부탁 한 줄. 의학적 효과를 단정하지 말 것('도움이 될 수 있어요' 정도). 바이노럴이면 헤드폰 안내.
- hashtags: 10~15개, 띄어쓰기로 구분, 한국어+영어 섞어서(#파도소리 #oceanwaves 등).
- tags: 유튜브 '태그' 칸용 키워드 15~25개를 쉼표로 구분(# 없이).
- pinned_comment: 시청자가 댓글 달고 싶어지는 한 줄 질문.
반드시 JSON만 출력: {"titles": ["..."], "description": "...", "hashtags": "#... #...", "tags": "a, b, c", "pinned_comment": "..."}"""


def media_duration(path):
    """영상 길이(초) - ffmpeg 정보에서 읽음"""
    p = subprocess.run([get_ffmpeg(), "-i", path], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, errors="replace",
                       creationflags=(subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0))
    m = re.search(r"Duration:\s*(\d+):(\d+):(\d+(?:\.\d+)?)", p.stderr or "")
    if not m:
        raise RuntimeError("영상 길이를 읽지 못했습니다: " + os.path.basename(path))
    return int(m.group(1)) * 3600 + int(m.group(2)) * 60 + float(m.group(3))


def media_size(path):
    p = subprocess.run([get_ffmpeg(), "-i", path], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, errors="replace",
                       creationflags=(subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0))
    m = re.search(r"Video:.*?(\d{3,5})x(\d{3,5})", p.stderr or "")
    return (int(m.group(1)), int(m.group(2))) if m else (1920, 1080)


def shorts_overlay(top, bottom, s, path):
    """쇼츠 위·아래 글자 (1080×1920 투명 PNG)"""
    layer = Image.new("RGBA", (1080, 1920), (0, 0, 0, 0))
    d = ImageDraw.Draw(layer)
    fp = s.get("title_font_path") or s.get("font_path")
    if top.strip():
        size = 92
        f = load_font(fp, size)
        lines = wrap(top.strip(), f, 960)
        while len(lines) > 3 and size > 50:
            size -= 6
            f = load_font(fp, size)
            lines = wrap(top.strip(), f, 960)
        y = 260 - (len(lines) - 1) * size * 0.6
        for ln in lines:
            x = (1080 - f.getlength(ln)) / 2
            d.text((x, y), ln, font=f, fill="#FFFFFF", stroke_width=max(5, size // 12), stroke_fill="#000000")
            y += size * 1.2
    if bottom.strip():
        f2 = load_font(s.get("font_path") or fp, 50)
        for i, ln in enumerate(wrap(bottom.strip(), f2, 960)[:2]):
            x = (1080 - f2.getlength(ln)) / 2
            d.text((x, 1560 + i * 64), ln, font=f2, fill="#FFE135", stroke_width=4, stroke_fill="#000000")
    layer.save(path)


def cut_short(src, out, start, length, top, bottom, s, mode="가운데"):
    """롱폼 영상의 한 구간 → 세로 쇼츠 (가운데 맞춤 + 흐린 배경, 또는 꽉 채우기) + 위·아래 글자 + 소리 페이드"""
    png = out + ".ov.png"
    shorts_overlay(top, bottom, s, png)
    w, h = media_size(src)
    if h >= w:   # 이미 세로 영상
        base = "[0:v]scale=1080:1920:force_original_aspect_ratio=increase,crop=1080:1920,setsar=1[v1]"
    elif mode.startswith("꽉"):
        base = "[0:v]scale=-2:1920,crop=1080:1920,setsar=1[v1]"
    else:
        base = ("[0:v]split=2[a][b];[a]scale=1080:1920:force_original_aspect_ratio=increase,crop=1080:1920,boxblur=24:2,eq=brightness=-0.12[bg];"
                "[b]scale=1080:-2[fg];[bg][fg]overlay=(W-w)/2:(H-h)/2,setsar=1[v1]")
    fc = base + ";[v1][1:v]overlay=0:0,format=yuv420p[v]"
    fo = max(0.0, length - 1.2)
    cmd = [get_ffmpeg(), "-y", "-v", "error", "-ss", f"{start:.2f}", "-t", f"{length:.2f}", "-i", src, "-i", png,
           "-filter_complex", fc, "-map", "[v]", "-map", "0:a?", "-af", f"afade=t=in:st=0:d=0.6,afade=t=out:st={fo:.2f}:d=1.2",
           "-c:v", "libx264", "-preset", "fast", "-crf", "23", "-r", "30", "-c:a", "aac", "-b:a", "160k", "-movflags", "+faststart", out]
    p = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, errors="replace",
                       creationflags=(subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0))
    try:
        os.remove(png)
    except OSError:
        pass
    if p.returncode != 0:
        raise RuntimeError("쇼츠 만들기 실패: " + (p.stderr or "")[-400:])


def hms(sec):
    sec = int(sec)
    return f"{sec // 3600}:{sec % 3600 // 60:02d}:{sec % 60:02d}" if sec >= 3600 else f"{sec // 60:02d}:{sec % 60:02d}"


def music_upload_text(title, preset_names, chapters=None, minutes=None):
    """음악 영상 업로드 문구 (제목 후보·설명·해시태그·고정 댓글)"""
    P = [MUSIC_PRESETS[n] for n in preset_names if n in MUSIC_PRESETS]
    tags = []
    for p in P:
        for tg in p["tags"].split():
            if tg not in tags:
                tags.append(tg)
    length = (f"{int(minutes // 60)}시간" if minutes and minutes >= 60 and minutes % 60 == 0
              else f"{int(minutes)}분" if minutes else "")
    titles = [f"{title}" + (f" | {length}" if length else ""),
              f"{(P[0]['desc'] if P else title).split(',')[0]} | " + (length or "") + " 🎧",
              f"[{length or 'Playlist'}] {title}"]
    lines = [title, ""]
    for p in P[:3]:
        lines.append("🎵 " + p["desc"])
    lines += ["", "공부할 때, 일할 때, 쉬거나 잠들기 전에 편하게 틀어 두세요.",
              "좋았다면 구독과 좋아요로 응원해 주세요 🙏", ""]
    if any(p["gen"] == "binaural" for p in P):
        lines += ["🎧 바이노럴 비트는 헤드폰(이어폰)으로 들어야 왼쪽·오른쪽 소리 차이가 전달됩니다. 운전 중에는 듣지 마세요.", ""]
    if chapters:
        lines += ["⏱ 목차"] + [f"{hms(t)} {n}" for t, n in chapters] + [""]
    lines += ["※ 이 영상의 음악은 프로그램으로 직접 만든 창작 음악입니다.", "※ 의학적 치료 효과를 보장하지 않습니다.", "", " ".join(tags[:12])]
    return {"titles": titles, "description": "\n".join(lines), "hashtags": " ".join(tags[:12]),
            "pinned_comment": "오늘 어떤 순간에 이 음악을 틀어 두셨나요? 🎧 (공부·일·잠들기 전·명상)"}


# ---------------- 화면(GUI) ----------------
class App(tk.Tk):
    def __init__(self):
        super().__init__()
        self.title("쇼츠 스크롤 영상 메이커 PRO (Claude Max) — 소설 · 실화 · 과학 · 자연현상")
        sh_ = self.winfo_screenheight()
        self.geometry(f"1460x{min(980, max(760, sh_ - 90))}")   # 화면이 작으면 창도 거기에 맞춤
        self.minsize(1200, 760)
        self.q = queue.Queue()
        self.renderer = None
        self.busy = False
        self.playing = False
        self.cancel = threading.Event()
        self.vars = {}
        self.cfg = self.load_cfg()
        self.build_ui()
        RATE_HOOK["cancel"] = self.cancel      # 성우 미리듣기처럼 따로 도는 작업도 한도 대기 표시
        RATE_HOOK["status"] = lambda msg: self.q.put(lambda m_=msg: self.set_status(m_))
        RATE_HOOK["log"] = lambda msg: self.q.put(lambda m_=msg: self.write_log(m_))
        self.apply_cfg()
        self.after(100, self.poll)
        self.after(300, self.refresh_preview)
        self.after(500, self.check_claude_ui)
        self.after(800, self.prepare_ffmpeg)
        self.protocol("WM_DELETE_WINDOW", self.on_close)

    # ---- 설정 저장/불러오기 ----
    def load_cfg(self):
        best = {}
        for p in (CONFIG_PATH, CONFIG_PATH2):
            try:
                with open(p, encoding="utf-8") as f:
                    c = json.load(f)
                if not best or os.path.getmtime(p) > best.get("_mt", 0):
                    c["_mt"] = os.path.getmtime(p)
                    best = c
            except Exception:
                pass
        best.pop("_mt", None)
        return best

    def project_dict(self):
        return {"ver": 7, "model": self.model_var.get(), "category": self.cat_var.get(), "topic": self.topic_var.get(), "genre": self.genre_var.get(),
                "sources": getattr(self, "sources", []), "notes": getattr(self, "notes", ""),
                "song": getattr(self, "song", None), "melody": getattr(self, "melody", ""), "bpm": getattr(self, "bpm", 90),
                "artwork": getattr(self, "artwork", None),
                "length": self.len_var.get(), "judge": self.judge_var.get(), "theme": self.theme_var.get(),
                "research": self.research_var.get(), "autophoto": self.autophoto_var.get(),
                "reference": getattr(self, "reference", ""), "img_prompts": getattr(self, "img_prompts", []),
                "para_audio": getattr(self, "para_audio", {}), "narr_style": getattr(self, "narr_style_cache", {}),
                "title": self.title_var.get(), "story": self.get_story(), "settings": self.get_settings()}

    def save_cfg(self, show=False):
        """설정(키·AI 엔진·디자인·소리 등) 저장. show=True면 결과를 알려줌"""
        data = self.project_dict()
        err = ""
        for p in (CONFIG_PATH, CONFIG_PATH2):
            try:
                tmp = p + ".tmp"
                with open(tmp, "w", encoding="utf-8") as f:
                    json.dump(data, f, ensure_ascii=False, indent=2)
                os.replace(tmp, p)
                if show:
                    self.write_log("설정 저장: " + p)
                    self.set_status("💾 설정 저장됨 (API 키·AI 엔진·디자인·소리) → 다음에 켜도 그대로")
                return True
            except Exception as e:
                err = str(e)
        if show:
            messagebox.showerror("설정 저장 실패", "설정 파일을 쓸 수 없어요.\n" + err)
        return False

    def apply_cfg(self, c=None):
        c = self.cfg if c is None else c
        self.model_var.set(c.get("model", ""))
        self.topic_var.set(c.get("topic", ""))
        cat = c.get("category", "허구 단편소설")
        self.cat_var.set(cat if cat in CATEGORIES else "허구 단편소설")
        topics = cat_info(self.cat_var.get())[1]
        self.genre_box.config(values=list(topics))
        g = c.get("genre", "")
        self.genre_var.set(g or list(topics)[0])
        self.research_var.set(bool(c.get("research", True)))
        self.autophoto_var.set(bool(c.get("autophoto", True)))
        self.set_reference(c.get("reference", ""))
        self.img_prompts = list(c.get("img_prompts") or [])
        self.para_audio = {str(k): v for k, v in (c.get("para_audio") or {}).items()}
        self.narr_style_cache = dict(c.get("narr_style") or {})
        self.set_sources(c.get("sources", []), c.get("notes", ""))
        self.song, self.melody, self.bpm = c.get("song"), c.get("melody", ""), c.get("bpm", 90)
        self.artwork = c.get("artwork")
        CURRENT_MELODY["melody"], CURRENT_MELODY["bpm"] = self.melody or "", self.bpm or 90
        self.len_var.set(c.get("length", "40"))
        self.judge_var.set(bool(c.get("judge", True)))
        self.theme_var.set(c.get("theme", "시네마 다크"))
        self.title_var.set(c.get("title", SAMPLE_TITLE))
        self.set_story(c.get("story", SAMPLE_STORY))
        s = dict(DEFAULTS)
        s.update(c.get("settings", {}))
        if c.get("settings") and c.get("ver", 1) < 2 and int(float(s.get("fps", 30))) == 30:
            s["fps"] = 60  # 부드러운 스크롤 기본값으로 올림
        if c.get("settings") and c.get("ver", 1) < 7:   # 허구 분위기 사진 자동 찾기는 옵션으로
            fi = str(s.get("fiction_image", ""))
            s["fiction_image"] = ("ChatGPT 그림 생성(API)" if fi.startswith("ChatGPT") else fi if fi.startswith("둘 다")
                                  else DEFAULTS["fiction_image"])
        if c.get("settings") and c.get("ver", 1) < 6:   # 자막형도 '글자' 탭 색을 따르게
            if s.get("head_style") == "흰색+하늘색":
                s["head_style"] = "글자 탭 제목색"
            if s.get("sub_style") == "흰글자+검은테두리":
                s["sub_style"] = "글자 탭 글자색+검은테두리"
        if c.get("settings") and c.get("ver", 1) < 5:
            if float(s.get("narr_duck", 0.5)) < 0.5:
                s["narr_duck"] = 0.5
            if float(s.get("hit_volume", 0.6)) == 0.8:
                s["hit_volume"] = 0.6
        if c.get("settings") and c.get("ver", 1) < 4 and str(s.get("gemini_model", "")).startswith("gemini-1."):
            s["gemini_model"] = "gemini-2.5-flash"   # 1.x 모델은 종료됨
        if c.get("settings") and c.get("ver", 1) < 3:
            s["grain"] = 0          # 노이즈는 용량을 크게 키움 → 끔
            if int(float(s.get("quality", 23))) < 23:
                s["quality"] = 23
        if c.get("settings", {}).get("img_zoom") == "off" and "img_motion" not in c.get("settings", {}):
            s["img_motion"] = "없음"
        if s.get("bgm_path") and "bgm_mode" not in c.get("settings", {}):
            s["bgm_mode"] = "파일"  # 예전 설정 호환
        self.set_settings(s)

    def on_close(self):
        try:
            self.save_cfg()
        finally:
            self.destroy()

    def open_project(self):
        p = filedialog.askopenfilename(filetypes=[("프로젝트", "*.json")])
        if p:
            with open(p, encoding="utf-8") as f:
                c = json.load(f)
            cur = self.get_settings()
            st = dict(c.get("settings") or {})
            for k in KEEP_KEYS:               # 내 키·AI 엔진 설정은 프로젝트를 열어도 그대로
                if not str(st.get(k, "")).strip() or k in SECRET_KEYS:
                    st[k] = cur.get(k, DEFAULTS.get(k, ""))
            c["settings"] = st
            self.apply_cfg(c)
            self.refresh_preview()

    def save_project(self):
        p = filedialog.asksaveasfilename(defaultextension=".json", filetypes=[("프로젝트", "*.json")],
                                         initialfile=safe_name(self.title_var.get()) + ".json")
        if p:
            d = self.project_dict()
            d["settings"] = {k: v for k, v in d["settings"].items() if k not in SECRET_KEYS}  # 키는 빼고 저장(공유해도 안전)
            with open(p, "w", encoding="utf-8") as f:
                json.dump(d, f, ensure_ascii=False, indent=2)
            self.write_log("프로젝트 저장: " + p)

    # ---- UI ----
    def build_ui(self):
        top = ttk.Frame(self, padding=(8, 6))
        top.pack(fill="x")
        ttk.Button(top, text="🆕 새로 만들기", command=self.new_project).pack(side="left", padx=(0, 4))
        ttk.Button(top, text="프로젝트 열기", command=self.open_project).pack(side="left")
        ttk.Button(top, text="프로젝트 저장", command=self.save_project).pack(side="left", padx=4)
        ttk.Button(top, text="💾 설정 저장", command=lambda: self.save_cfg(show=True)).pack(side="left")
        ttk.Separator(top, orient="vertical").pack(side="left", fill="y", padx=8)
        ttk.Label(top, text="Claude 상태").pack(side="left")
